INSERT INTO `ps_product_lang` (`id_product`, `id_shop`, `id_lang`, `description`, `description_short`, `link_rewrite`, `meta_description`, `meta_keywords`, `meta_title`, `name`, `available_now`, `available_later`, `delivery_in_stock`, `delivery_out_stock`) VALUES
(835, 1, 1, 'Kompozycja zielonej herbaty Gunpowder, w której skrywa się zdrowotne bogactwo pokrzywy oraz aloesu, okraszone wonnymi płatkami róży. Aloes jest niesamowitą roślina leczniczą pełną drogocennych wartości odżywczych. Zawiera wiele witamin, w tym A, C, E, kwas foliowy (B9), B1, B2, B3 (niacyna), B6. Aloes jest również jedyną z niewielu roślin zawierających witaminę B12. Zawiera także wiele niezbędnych mikroelementów: wapń, magnez, cynk, chrom, selen, sód, potas, żelazo, miedź oraz mangan. Pomaga także w oczyszczaniu organizmu oraz w trawieniu pokarmu.', 'Zielona kompozycja 70g', 'dzikujaloevera', '', '', '', 'DZIĘKUJĘ! ALOE VERA', '', '', '', ''),
(836, 1, 1, 'Wspaniale fantazyjne połączenie owoców: jabłka, papai, owocu czarnego bzu, maliny oraz truskawki w towarzystwie hibiskusa, delikatnych płatków słonecznika i aromatycznego bławatka. Z każdym kolejnym łykiem przenosi nas w cudowny klimat egzotyki. Wyśmienita do podawania jako słodki dodatek podczas spotkań z rodziną czy przyjaciółmi.', 'Owocowa kompozycja 70g', 'dzikujborabora', '', '', '', 'DZIĘKUJĘ! BORA BORA', '', '', '', ''),
(837, 1, 1, 'Cytrusowy smak cząstek mandarynki, orzeźwiająca skórka pomarańczy, a także wonne płatki róży, które otulają czarną, wietnamską herbatę to idealne zaproszenie do popołudniowego relaksu w towarzystwie książki czy w gronie przyjaciół. Jasnozłoty napar to prawdziwa feeria smaków: słodko-kwaśny charakter owoców doskonale uzupełnia kwiatowy akcent płatków róży.', 'Kompozycja czarna 70g', 'dzikujhiszpaska', '', '', '', 'DZIĘKUJĘ! HISZPAŃSKA', '', '', '', ''),
(838, 1, 1, 'Kompozycja zielonej herbaty Gunpowder, w której skrywa się zdrowotne bogactwo pokrzywy oraz aloesu, okraszone wonnymi płatkami róży. Aloes jest niesamowitą roślina leczniczą pełną drogocennych wartości odżywczych. Zawiera wiele witamin, w tym A, C, E, kwas foliowy (B9), B1, B2, B3 (niacyna), B6. Aloes jest również jedyną z niewielu roślin zawierających witaminę B12. Zawiera także wiele niezbędnych mikroelementów: wapń, magnez, cynk, chrom, selen, sód, potas, żelazo, miedź oraz mangan. Pomaga także w oczyszczaniu organizmu oraz w trawieniu pokarmu.', 'Zielona kompozycja 70g', 'flowerpoweraloevera', '', '', '', 'FLOWER POWER ALOE VERA', '', '', '', ''),
(839, 1, 1, 'Interesujące zestawienie klasycznej herbaty Earl Grey z kawałkami ożywczej pomarańczy. Kompozycję stworzono na bazie dwóch czarnych herbat: wietnamskiej oraz cejlońskiej. Dzięki cząsteczkom cytrusa herbata posiada niesamowicie egzotyczną i orzeźwiającą nutę, jednocześnie nie tracąc swojego wykwintnego charakteru. To doskonała propozycja uzupełniająca każde spotkanie towarzyskie. Herbata Earl Grey swój niepowtarzalny smak i aromat zawdzięcza olejkowi z bergamotki. Nazwę bergamotka wprowadzili Turcy określając tym mianem uprawiany w strefie śródziemnomorskiej owoc Książęcej Gruszki zbliżony kształtem do owoców cytrusowych, posiadający grubą, mięsistą skórkę. Właśnie z tej skóry tłoczony jest aromatyczny olejek dodawany między innymi do herbat typu Earl Grey.', 'Czarna kompozycja Earl Grey 70g', 'flowerpowermadamgrey', '', '', '', 'FLOWER POWER MADAM GREY', '', '', '', ''),
(840, 1, 1, 'Wyjątkowa propozycja, która z każdym kolejnym łykiem otula nas przyjemnym zapachem domowego ogniska. Skórka cytryny, wyraziste maliny oraz delikatne jabłko rozpływające się wokół listków wietnamskiej czarnej herbaty to idealna propozycja na długie jesienne wieczory. Jej lekko cytrusowa nuta w połączeniu z kostkami lodu, świeżą miętą i owocami sprawdzi się także jako kojący napój w letnie dni.', 'Czarna kompozycja 70g', 'flowerpowersercematki', '', '', '', 'FLOWER POWER SERCE MATKI', '', '', '', ''),
(841, 1, 1, 'Kubki w sercu - Gustav Klimt Adele (532-0805) to zestaw dwóch kubków o oryginalnych kształtach wraz z sercem. Wszystko ozdobione dziełami Klimta. Artysta zachwycał i zachwyca. inspiruje współczesnych ludzi do tworzenia nowej rzeczywistości. Kreowania otaczaj świata można zacząć od poranki i przyjemności picia z unikatowych kubków. Z pewnością koczujemy powiew kultury i sztuki w naszej kuchni.', 'Zestaw kubków w prezentowym opakowaniu - 2x270ml.', 'kubkiwsercuklimt', '', '', '', 'KUBKI W SERCU KLIMT', '', '', '', ''),
(842, 1, 1, 'Czarujący komplet w skład którego wchodzą dwa kubeczki o przepięknym kształcie, zdobione polnymi kwiatami. Dopełnieniem zestawu jest wysokiej jakości pudełko w kształcie serca także ozdobione polnymi kwiatami.', 'Zestaw kubków w prezentowym opakowaniu - 2x270ml.', 'kubkiwsercukwiaty', '', '', '', 'KUBKI W SERCU KWIATY', '', '', '', ''),
(843, 1, 1, 'Główni bohaterowie, czyli malina i płatki róży wraz ze swoim kompanem jabłkiem, porywają nas do świata pełnego kolorów (za sprawą bławatka i nagietka), w którym akcja toczy się wśród liści czarnej herbaty Ceylon. Limit dziennego spożycia 4 filiżanki.', 'Czarna kompozycja 70g', 'laurkaimiry', '', '', '', 'LAURKA: IMIĘ RÓŻY', '', '', '', ''),
(844, 1, 1, 'Pełne smaku połączenie papai, mango, jabłka, pomarańczy, skórki owocu granatu oraz safloru. Słodycz owoców jest znakomicie zrównoważona przez lekką kwasowość hibiskusa.', 'Owocowa kompozycja 70g', 'laurkaogrodyedenu', '', '', '', 'LAURKA: OGRODY EDENU', '', '', '', ''),
(845, 1, 1, 'Wyjątkowa kompozycja zielonej herbaty Sencha, białej herbaty Pai Mu Tan, soczystego ananasa, słodko-drzewnego sandałowca oraz orzeźwiającej trawy cytrynowej. Wyśmienita do podawania podczas wieczornych spotkań z przyjaciółmi i rodziną.', 'Owocowa kompozycja 70g', 'laurkasekretpikna', '', '', '', 'LAURKA: SEKRET PIĘKNA', '', '', '', ''),
(846, 1, 1, 'Interesujące zestawienie klasycznej herbaty Earl Grey z kawałkami ożywczej pomarańczy. Kompozycję stworzono na bazie dwóch czarnych herbat: wietnamskiej oraz cejlońskiej. Dzięki cząsteczkom cytrusa herbata posiada niesamowicie egzotyczną i orzeźwiającą nutę, jednocześnie nie tracąc swojego wykwintnego charakteru. To doskonała propozycja uzupełniająca każde spotkanie towarzyskie. Herbata Earl Grey swój niepowtarzalny smak i aromat zawdzięcza olejkowi z bergamotki. Nazwę bergamotka wprowadzili Turcy określając tym mianem uprawiany w strefie śródziemnomorskiej owoc Książęcej Gruszki zbliżony kształtem do owoców cytrusowych, posiadający grubą, mięsistą skórkę. Właśnie z tej skóry tłoczony jest aromatyczny olejek dodawany między innymi do herbat typu Earl Grey.', 'Earl Grey z pomarańczą 70g', 'zmiocimadamgrey', '', '', '', 'Z MIŁOŚCIĄ MADAM GREY', '', '', '', ''),
(847, 1, 1, 'Zestaw prezentowy zawiera:', 'Zestaw prezentowy ze słodkościami.', 'zestawbogactwosmakwduy', '', '', '', 'ZESTAW BOGACTWO SMAKÓW DUŻY', '', '', '', ''),
(848, 1, 1, 'Zestaw prezentowy zawiera:', 'Zestaw prezentowy ze słodkościami.', 'zestawbogactwosmakwmay', '', '', '', 'ZESTAW BOGACTWO SMAKÓW MAŁY', '', '', '', ''),
(849, 1, 1, 'Kawy smakowe należą do naszych specjalności. Niezwykłe propozycje komponowane są w oparciu o kolumbijską kawę Excelso z odmiany arabika, której walory doskonale współgrają z najróżniejszymi aromatami. To niesamowite, jakimi smakami może oczarować nas kawa, zachowując przy tym odpowiednie proporcje i balans. Postanowiliśmy sprostać oczekiwaniom kawoszy, którzy lubią zaskakujące połączenia i z myślą o nich przygotowaliśmy kilka ciekawych propozycji.', 'Zestaw kaw ziarnistych 10 x 50g', 'zestawdegustacyjnykawysmakowe', '', '', '', 'ZESTAW DEGUSTACYJNY KAWY SMAKOWE', '', '', '', ''),
(850, 1, 1, 'Zanurz się w świecie aromatycznych herbat dzięki naszemu starannie dobranemu zestawowi, który sprawi, że każdy dzień nabierze wyjątkowego smaku. Idealny na poranne pobudzenie, popołudniowe wyciszenie lub wieczorny relaks.', 'Podwójny zestaw herbaciany.', 'zestawdwieherbatynarcyzy', '', '', '', 'ZESTAW DWIE HERBATY NARCYZY', '', '', '', ''),
(851, 1, 1, 'Zanurz się w świecie aromatycznych herbat dzięki naszemu starannie dobranemu zestawowi, który sprawi, że każdy dzień nabierze wyjątkowego smaku. Idealny na poranne pobudzenie, popołudniowe wyciszenie lub wieczorny relaks.', 'Zestaw prezentowy zawierający dwie herbaty', 'zestawdwieherbatyowocowe', '', '', '', 'ZESTAW DWIE HERBATY OWOCOWE', '', '', '', ''),
(852, 1, 1, 'Zestaw Herbaciany – Twoja Codzienna Przyjemność', 'Zestaw prezentowy zawierający dwie uniwersalne herbaty.', 'zestawdwieherbatyserca', '', '', '', 'ZESTAW DWIE HERBATY SERCA', '', '', '', ''),
(853, 1, 1, 'Zestaw prezentowy zawiera:  - Herbatę zielona Aloe Vera 70g w kartoniku okazjonalnym - Herbatę czarną kompozycję Earl Grey Madam Grey 70g w kartoniku okazjonalnym - Pudełko eco z okienkiem przewiązane rafią', 'Zestaw prezentowy zawierający dwie uniwersalne herbaty.', 'zestawflowerpowerdwieherbaty', '', '', '', 'ZESTAW FLOWER POWER DWIE HERBATY', '', '', '', ''),
(854, 1, 1, 'Zanurz się w świecie aromatycznych herbat dzięki naszemu starannie dobranemu zestawowi, który sprawi, że każdy dzień nabierze wyjątkowego smaku. Idealny na poranne pobudzenie, popołudniowe wyciszenie lub wieczorny relaks.', 'Uniwersalny zestaw prezentowy', 'zestawherbacianabomba', '', '', '', 'ZESTAW HERBACIANA BOMBA', '', '', '', ''),
(855, 1, 1, 'Prowincja Assam to region na północnym wschodzie Indii, gdzie uprawia się odmianę herbaty o nazwie Camellia assamica. Ze względu na wysoką jakość liście tej odmiany są często stosowane do uszlachetniania mieszanek herbat niższego gatunku. Herbaty z regionu Assam są zaliczane do pięciu najlepszych herbat na świecie. Standard TGFOP (Tippy Golden Flowery Orange Pekoe) oznacza główną klasę herbat pochodzących z regionów Assam oraz Darjeeling, zawierających duże ilości tzw. złotych tipsów, czyli dwóch pierwszych listków z krzewu wraz z pączkami. Napar posiada barwę brązowo-bursztynową i mocny, cierpkawy, ale równocześnie słodki smak. Filiżanka herbaty Assam dodaje energii i doskonale orzeźwia.', 'Herbata czarna Assam Dekorai 50g w puszce.', 'assamdekoraipuszkaczarna', '', '', '', 'ASSAM DEKORAI PUSZKA CZARNA', '', '', '', ''),
(856, 1, 1, 'Wspaniałe, korzenne połączenie czarnej wietnamskiej herbaty z zielonymi listkami herbaty Sencha. Oryginalności dodają kawałki cynamonu, skórka pomarańczowa, płatki róży oraz słodkie rodzynki. Złocisty cynamonowo-pomarańczowy napar umili długie jesienne i zimowe wieczory, rozgrzewając oraz wprowadzając nas w wyjątkowy nastrój.', 'Herbata czarna OP oraz Sencha 70g', 'dlamczyznychwilaprzykominku', '', '', '', 'DLA MĘŻCZYZNY CHWILA PRZY KOMINKU', '', '', '', ''),
(857, 1, 1, 'Popularna kompozycja dwóch czarnych herbat gatunków Assam i Cejlon. Dedykowana jest do spożycia w godzinach porannych. Charakteryzuje się mocnym i wyrazistym smakiem i brązowo-bursztynową barwą. Herbata English Breakfast według wielu źródeł została wymyślona przez XIX–wiecznego brytyjskiego kupca z przeznaczeniem do spożycia przy śniadaniu. Duża moc naparu miała wpłynąć pobudzającą na pijącą ją osobę. Obecnie praktycznie każdy szanujący się producent herbaty posiada w ofercie autorską wersję kompozycji i nazywa ją oczywiście… English Breakfast, chociaż częstokroć znacznie różnią się między sobą zawartością. W naszym przypadku jest to kompozycja gatunkowych czarnych herbat pochodzących z Indii i Cejlonu.', 'Czarna herbata 70g', 'dlamczyznyenglishbreakfast', '', '', '', 'DLA MĘŻCZYZNY ENGLISH BREAKFAST', '', '', '', ''),
(858, 1, 1, 'Herbata która po otwarciu roztacza wokół cudownie słodki zapach wiśni, skąpanych w finezyjnym aromacie rumu. Łagodny smak czarnej wietnamskiej herbaty, który miesza się z wyrazistym wiśniowym dodatkiem to propozycja na każdy dzień. Idealna podczas długiego dnia w pracy czy na spotkaniu z przyjaciółmi.', 'Czarna kompozycja Wiśnie w rumie 70g', 'dlamczyznywiniezrumem', '', '', '', 'DLA MĘŻCZYZNY WIŚNIE Z RUMEM', '', '', '', ''),
(859, 1, 1, 'Pozwól rozgrzać się odważnemu smakowi czarnej herbaty Ceylon z dodatkiem imbiru, czerwonego pieprzu i kardamonu oraz oleju z bergamoty.', 'Herbata czarna Earl Grey Spicy 50g w puszce.', 'earlgreyspicypuszkaczarna', '', '', '', 'EARL GREY SPICY PUSZKA CZARNA', '', '', '', ''),
(860, 1, 1, 'Odwiedź pełną bergamotkowej magii krainę, w której wśród zielonej herbaty Sencha skosztujesz owoców winogron i wiśni, zachwycisz się aromatem werbeny oraz odpoczniesz wśród kwiatów rumianku i bławatka.', 'Zielona kompozycja Earl grey Fantasy 70g', 'kadafiliankaearlgrey', '', '', '', 'KAŻDA FILIŻANKA... EARL GREY', '', '', '', ''),
(861, 1, 1, 'Herbata czarna Ceylon High Grown z dodatkiem liści limonki, maliny oraz olejku z owoców bergamotki.  Składniki: herbata czarna Ceylon High Grown, limonka liść, malina liofilizowana, aromat  Wartość odżywcza w 100g: wartość energetyczna 63,0 kJ / 15,0 kcal, tłuszcze 0,0 g, węglowodany 1,8g (w tym cukry 1,5g), błonnik 2,2g, białko 0,0 g, sól 0,0g, sód 0,0g.', 'Czarna kompozycja 70g', 'kadafiliankawehikuczasu', '', '', '', 'KAŻDA FILIŻANKA... WEHIKUŁ CZASU', '', '', '', ''),
(862, 1, 1, 'Herbatę zieloną Sencha otrzymuje się poddając suszeniu liście niezwłocznie po zerwaniu ich z krzewu, tak aby nie dopuścić do rozpoczęcia procesu utleniania. Dzięki temu utrzymuje ona więcej składników o leczniczych właściwościach, oraz posiada wiele walorów smakowych (ziołowy aromat oraz wyraźnie delikatniejszy smak niż pozostałe rodzaje herbat). Nasza Japońska Sencha pochodzi z chińskich plantacji, ale przygotowywana jest na sposób japoński. Obowiązujące w Japonii standardy dotyczące uprawy krzewów herbaty i obróbki suszu sprawiają, że herbata otrzymywana tą metodą jest najwyższej jakości.', 'Herbata zielona Sencha Japan style 50g w puszce.', 'senchajapanstylepuszkaczarna', '', '', '', 'SENCHA JAPAN STYLE PUSZKA CZARNA', '', '', '', ''),
(863, 1, 1, 'Herbatę zieloną Sencha otrzymuje się poddając suszeniu liście niezwłocznie po zerwaniu ich z krzewu, tak aby nie dopuścić do rozpoczęcia procesu utleniania. Dzięki temu utrzymuje ona więcej składników o leczniczych właściwościach, oraz posiada wiele walorów smakowych (ziołowy aromat oraz wyraźnie delikatniejszy smak niż pozostałe rodzaje herbat). Nasza Japońska Sencha pochodzi z chińskich plantacji, ale przygotowywana jest na sposób japoński. Obowiązujące w Japonii standardy dotyczące uprawy krzewów herbaty i obróbki suszu sprawiają, że herbata otrzymywana tą metodą jest najwyższej jakości.', 'Herbata zielona 70g', 'zprzyjacielemsenchajapanstyle', '', '', '', 'Z PRZYJACIELEM: SENCHA JAPAN STYLE', '', '', '', ''),
(864, 1, 1, 'Zanurz się w świecie aromatycznych herbat dzięki naszemu starannie dobranemu zestawowi, który sprawi, że każdy dzień nabierze wyjątkowego smaku. Idealny na poranne pobudzenie, popołudniowe wyciszenie lub wieczorny relaks.', 'Zestaw prezentowy ze słodkościami.', 'zestawdlamczyzny', '', '', '', 'ZESTAW DLA MĘŻCZYZNY', '', '', '', ''),
(865, 1, 1, 'Zestaw prezentowy zawiera:  - Herbatę czarną Ceylon High Grown OP 70g w kartoniku okazjonalnym - Herbatę czarną English Brakfast 70g w kartoniku okazjonalnym - Pudełko eco z okienkiem przewiązane rafią', 'Zestaw prezentowy zawierający dwie czarne herbaty.', 'zestawdwieherbatyczarne', '', '', '', 'ZESTAW DWIE HERBATY CZARNE', '', '', '', ''),
(866, 1, 1, 'Zestaw prezentowy zawiera:  - Kawę ziarnistą Kolumbia Medelin 100g w kartoniku okazjonalnym - Kawę ziarnistą Gwatemala Maragogype 100g w kartoniku okazjonalnym - Pudełko eco z okienkiem przewiązane rafią', 'Zestaw prezentowy zawierający dwie kawy.', 'zestawdwiekawyklasyczne', '', '', '', 'ZESTAW DWIE KAWY KLASYCZNE', '', '', '', ''),
(867, 1, 1, 'Zestaw prezentowy zawiera:  - Kawę ziarnistą pomarańczowa 100g w kartoniku okazjonalnym - Kawę ziarnistą waniliową-orzechową 100g w kartoniku okazjonalnym - Pudełko eco z okienkiem przewiązane rafią', 'Zestaw prezentowy zawierający dwie kawy.', 'zestawdwiekawysmakowe', '', '', '', 'ZESTAW DWIE KAWY SMAKOWE', '', '', '', ''),
(868, 1, 1, 'Idealny pomysł na prezent! Zestaw zapakowany w eleganckie opakowanie sprawdzi się doskonale jako prezent dla bliskiej osoby – na urodziny, święta czy bez okazji.', 'Zestaw prezentowy w skrzynce', 'zestawherbataikawaskrzynkaaur', '', '', '', 'ZESTAW HERBATA I KAWA SKRZYNKA AŻUR', '', '', '', ''),
(869, 1, 1, 'Zanurz się w świecie aromatycznych herbat dzięki naszemu starannie dobranemu zestawowi, który sprawi, że każdy dzień nabierze wyjątkowego smaku. Idealny na poranne pobudzenie, popołudniowe wyciszenie lub wieczorny relaks.', 'Podwójny zestaw herbaciany.', 'zestawkompozycjeczarne', '', '', '', 'ZESTAW KOMPOZYCJE CZARNE', '', '', '', ''),
(870, 1, 1, 'Zestaw składający się z Yerba Mate Lemon 400g (Yerba Mate z dodatkiem skórki cytryny, trawy cytrynowej i liści limonki tworzy rześką kompozycję, której nie można się oprzeć), ceramicznego żółtego matero oraz bombilli.', 'Yerba Mate Lemon 400g, matero i bombilla.', 'zestawmatelemon', '', '', '', 'ZESTAW MATE LEMON', '', '', '', ''),
(871, 1, 1, 'Zestaw składający się z Yerba Mate Very Berry 400g (brazylijska Yerba Mate oraz delikatne jagody, słodkie maliny i kwaśne porzeczki to połączenie, które doskonale się uzupełnia.), ceramicznego czarnego matero oraz bombilli.', 'Yerba Mate Very Berry 400g, matero i bombilla.', 'zestawmateveryberry', '', '', '', 'ZESTAW MATE VERY BERRY', '', '', '', ''),
(872, 1, 1, 'Zestaw składający się z Yerba Mate Wild Energy 400g (połączenia Yerba Mate, guarany i żeń-szenia, które doda nowych sił do działania, a soczysty ananas, maliny i aromatyczna skórka pomarańczy apetycznie dopełni całości), ceramicznego czerwonego matero oraz bombilli.', 'Yerba Mate Wild Energy 400g, matero i bombilla.', 'zestawmatewildenergy', '', '', '', 'ZESTAW MATE WILD ENERGY', '', '', '', ''),
(873, 1, 1, 'Zestaw składający się z Yerba Mate Cannabis 200g (yerba mate 90%, suszone liście konopi 10%), ceramicznego zielonego matero oraz bombilli.', 'Yerba Mate Cannabis 200g, matero i bombilla.', 'zestawminimatecannabis', '', '', '', 'ZESTAW MINI MATE CANNABIS', '', '', '', ''),
